 static final int BG=0xff0b141e, PANEL=0xff182735, GREEN=0xff78f0b4, WHITE=0xffecf6f2;
 final ExecutorService io=Executors.newSingleThreadExecutor();final Pad pad=new Pad();android.content.SharedPreferences prefs;Auth auth;LinearLayout root,body,tabs;TextView notice,hud;NativePlayer nativePlayer;WebPlayer webPlayer;WebView official;JSONArray catalog=new JSONArray(),recent=new JSONArray();List<JSONObject> filtered=new ArrayList<>();String tab="home",query="";int page,epoch;volatile boolean busy;boolean playing;ListView list;
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("settings",0);auth=new Auth(this,prefs.getString("client",Auth.DEFAULT_CLIENT));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);home();}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(WHITE);t.setTextSize(size);t.setPadding(dp(8),dp(5),dp(8),dp(5));return t;}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(8));return d;}
 android.graphics.drawable.StateListDrawable focus(){android.graphics.drawable.StateListDrawable d=new android.graphics.drawable.StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},shape(GREEN));d.addState(new int[]{android.R.attr.state_pressed},shape(GREEN));d.addState(new int[]{},shape(PANEL));return d;}
 Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(new ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[]{}},new int[]{BG,WHITE}));b.setBackground(focus());b.setPadding(dp(12),dp(4),dp(12),dp(4));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(48));p.setMargins(dp(4),dp(4),dp(4),dp(4));b.setLayoutParams(p);b.setOnClickListener(v->action.run());return b;}
